"""One learner per team of a run (TRAIN-07)."""

import numpy as np

from rllab.core import RunConfig, WorldSpec
from rllab.methods import Learner, make_learner


def make_learners(config: RunConfig, spec: WorldSpec) -> dict[str, Learner]:
    """One learner per team of `spec`, each built from its team's method config.

    Team i's generator is the i-th child spawned from the run seed (AD-05), so the same config
    gives the same learners and no two teams share a generator.
    """
    children = np.random.SeedSequence(config.seed).spawn(len(spec.teams))
    return {
        team.name: make_learner(
            config.methods[team.name], spec, team.name, np.random.default_rng(child)
        )
        for team, child in zip(spec.teams, children, strict=True)
    }

